def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def combinations(items, k):
    items = list(items)
    n = len(items)
    if k > n or k < 0:
        return
    if k == 0:
        yield ()
        return
    for i in range(n - k + 1):
        for rest in combinations(items[i + 1:], k - 1):
            yield (items[i],) + rest

def bad_config(s, r):
    for sub in combinations(s, r):
        first = None
        same = True
        for a, b in combinations(sub, 2):
            g = gcd(a, b)
            if first is None:
                first = g
            elif g != first:
                same = False
                break
        if same and first is not None:
            return True
    return False

def f3(N, r):
    best = 0
    for mask in range(1, 2 ** N):
        s = [i + 1 for i in range(N) if (mask >> i) & 1]
        if len(s) > best and not bad_config(s, r):
            best = len(s)
    return best

def require(cond, msg):
    if not cond:
        raise ValueError('VERIFY_FAIL: ' + msg)

def verify(witness):
    r = witness['r']
    require(r == 3, 'r')
    vals = witness['f3_values_N_1_to_8']
    require(isinstance(vals, list) and len(vals) == 8, 'len')
    for N in range(1, 9):
        require(f3(N, r) == vals[N - 1], 'value at N')
    require(vals[7] == 4, 'N8')
    ext = witness['extremizer_N8']
    require(len(ext) == 4 and not bad_config(ext, r), 'extremizer')
    ch = witness['dyadic_chain_N8']
    require(ch == [2 ** i for i in range(len(ch))], 'dyadic form')
    pairs = list(combinations(ch, 2))
    gs = []
    for a, b in pairs:
        g = gcd(a, b)
        if g not in gs:
            gs.append(g)
    require(len(gs) == len(pairs), 'dyadic distinct gcds')
    require(len(ch) == vals[7], 'dyadic size')
